// Language: German is in the markup, English comes from the EN table.
const $=id=>document.getElementById(id);
// Language: German is written in the markup; English comes from this table. Choice is kept per browser.
let L='de';try{L=localStorage.getItem('lang')||(/^de/i.test(navigator.language)?'de':'en')}catch{L=/^de/i.test(navigator.language)?'de':'en'}
const t=(de,en)=>L==='en'?en:de;
const EN={"Bücher auswählen": "Choose books","Ohne Auswahl nimmt der Assistent die deutsche und englische Wikipedia. Wikipedia-Bücher beantworten „Was ist …?“, die übrigen durchsucht er bei „Schau in meinem Archiv …“. Höchstens 10, danach speichern.": "Without a choice the assistant uses the German and English Wikipedia. Wikipedia books answer \"What is …?\", it searches the others for \"Look in my archive …\". At most 10, then save.","Eigenes Kiwix-Archiv": "Own Kiwix archive","Wissen aus deinem kiwix-serve, auch ohne Internet. Fällt die Websuche aus, antwortet der Assistent daraus.": "Knowledge from your kiwix-serve, also without internet. If the web search fails, the assistant answers from it.","Adresse des Kiwix": "Kiwix address","Am besten die Adresse im Heimnetz: schneller und geht ohne Internet. Ändern braucht den zweiten Anmeldeschritt.": "Best use the home network address: faster and works without internet. Changing it needs the second sign-in step.","Bücher": "Books","leer = alle, höchstens 10": "empty = all, at most 10","Bücher laden": "Load books","Antippen nimmt ein Buch in die Liste auf oder heraus; danach speichern. Wikipedia-Bücher beantworten „Was ist …?“, die übrigen durchsucht der Assistent bei „Schau in meinem Archiv …“.": "Tap a book to add it to or remove it from the list, then save. Wikipedia books answer \"What is …?\", the assistant searches the others for \"Look in my archive …\".","Kiwix-Archiv": "Kiwix archive","Prüft, ob der Spark dein Kiwix erreicht, welche Bücher es hat und wie schnell eine Testsuche antwortet. Adresse und Schalter unter Einstellungen → Funktionen → Websuche.": "Checks whether the Spark reaches your Kiwix, which books it has and how fast a test search answers. Address and switch under Settings → Features → Web search.","Kiwix prüfen": "Check Kiwix","Benutzer als Admin": "Users as admins","Benutzer als Admin erlauben": "Allow users as admins","Ausgewählte Profile verwalten den Spark mit eigener Anmeldung und eigenem Code.": "Chosen profiles manage the Spark with their own sign-in and their own code.","wirkt sofort, mit Code": "takes effect at once, with a code","Admin-Protokoll": "Admin log","Mit-Admin: alles wie der Admin, außer Admin-Passwort und zweitem Schritt des Admins, Rollen, Sicherungen einspielen oder herunterladen und Profile mit Admin-Rolle ändern. Verwalter: nur Zustand, Logs, Profile und Geräte, Funktionen ein und aus. Eine Rolle allein gibt nichts: Das Profil braucht seinen zweiten Anmeldeschritt und öffnet unter Ich → Sicherheit den Admin-Modus mit einem frischen Code; er endet nach 15 Minuten ohne Bedienung, spätestens nach 8 Stunden. Über Sprache, Lautsprecher, Uhr, Telegram und Siri wirkt die Rolle nie. Schalter aus oder Rolle entziehen beendet jeden offenen Admin-Modus sofort. Was ein Profil als Admin tut, steht unter Zustand → Logs → Admin-Protokoll.": "Co-admin: everything like the admin, except the admin password and the admin's second step, roles, restoring or downloading backups and changing profiles with an admin role. Manager: only status, logs, profiles and devices, functions on and off. A role alone gives nothing: the profile needs its second login step and opens the admin mode under Me → Security with a fresh code; it ends after 15 minutes without use, after 8 hours at the latest. The role never works through speech, speakers, the watch, Telegram or Siri. Switching it off or taking the role away ends every open admin mode at once. What a profile does as admin is listed under Status → Logs → Admin log.","Auswahl passend zum gewählten Modell.": "Choice to match the selected model.","Wikipedia direkt": "Wikipedia straight away","Wissensfragen wie „Was ist ein Quasar?“ beantwortet der Assistent aus dem Wikipedia-Artikel, ohne Websuche.": "Knowledge questions like “What is a quasar?” are answered from the Wikipedia article, without a web search.","Adresse der Wikipedia": "Wikipedia address","Leer = de.wikipedia.org, ohne Treffer dort en.wikipedia.org. Nur die Suchwörter verlassen den Spark.": "Empty = de.wikipedia.org, with no hit there en.wikipedia.org. Only the search words leave the Spark.","Rollen per Sprache": "Roles by voice","Profile speichern eigene Rollen und wechseln mit „Sei jetzt …“; das Panel schaltet, die Rolle ändert nur den Ton.": "Profiles save their own roles and switch with “Be … now”; the panel switches, the role only changes the tone.","Panel-Bereiche in der iPhone-App": "Panel areas in the iPhone app","Die App übernimmt Teile des Panels, etwa Gedächtnis, Termine und „Spark verwalten“. Jedes Profil schaltet jeden Bereich einzeln ein.": "The app takes over parts of the panel, such as memory, appointments and \"Manage the Spark\". Each profile switches on each area on its own.","Steckbrief und Tags": "Document card and tags","Das Sprachmodell notiert in Pausen Titel, Art, Absender, Frist und Schlagwörter jedes Dokuments; der Assistent sucht damit gezielter.": "In quiet minutes the language model notes title, kind, sender, deadline and keywords of each document; the assistant searches more precisely.","Größte PDF-Datei (MB)": "Largest PDF file (MB)","20 bis 300, Standard 100. Andere Dateiarten bis 20 MB. Große Scans brauchen beim Hochladen kurz etwa das Dreifache an Arbeitsspeicher.": "20 to 300, default 100. Other kinds of files up to 20 MB. Big scans briefly need about three times their size in memory while uploading.","Lange Dokumente nachts lesen": "Read long documents at night","Tagsüber nur kurze Dokumente (bis 10 Seiten) in Pausen, lange erst nach 30 Minuten Ruhe oder im Nachtfenster, dort bis 400 Seiten mehr.": "By day only short documents (up to 10 pages) in quiet moments, long ones only after 30 minutes of quiet or in the night window, there up to 400 more pages.","Nachtfenster": "Night window","bis": "to","Uhr-App „Spark“ per Einrichtungscode koppeln statt Adresse und Schlüssel abzutippen. Der Uhr-Schlüssel darf nur fragen.": "Pair the \"Spark\" watch app with a setup code instead of typing address and key. The watch key may only ask.","Pebble-Uhr koppeln": "Pair the Pebble watch","Eigene Dokumente": "Own documents","Profilnamen, Speicher und Zahlen, nie Inhalte. Dokumentnamen nur, wenn jemand ein Dokument für alle freigegeben hat.": "Profile names, space and numbers, never contents. Document names only when someone shared a document for everyone.","Von anderen für alle freigegeben": "Shared for everyone by others","Gemeinsame Dokumente": "Shared documents","Ein Profil gibt einzelne Dokumente „Für alle“ frei, die anderen Profile finden und öffnen sie. Gäste und unbekannte Stimmen nie.": "A profile shares single documents \"for everyone\", the other profiles find and open them. Never guests or unknown voices.","Vorrang für Sprache": "Speech first","Vorrang prüfen": "Check priority","Spracherkennung und Sprachausgabe gehen immer vor: Hintergrundarbeit wartet, solange gesprochen wird, und eine laufende Hintergrund-Anfrage an das Sprachmodell wird abgebrochen und später wiederholt. Der Test spricht einen Satz dreimal: alleine, während das Sprachmodell eine lange Antwort schreibt, und dasselbe mit Vorfahrt. Dauert etwa eine Minute.": "Speech recognition and speech output always come first: background work waits while someone speaks, and a running background request to the language model is cancelled and repeated later. The test speaks one sentence three times: alone, while the language model writes a long answer, and the same with priority. Takes about a minute.","Bilder und Scans lesen": "Read pictures and scans","Fotos und gescannte PDF-Seiten liest das Sprachmodell einmal in Gesprächspausen ab; danach findet die Dokumentensuche ihren Text.": "The language model reads photos and scanned PDF pages once in quiet moments; the document search then finds their text.","Bedeutungssuche": "Meaning search","Ein kleines Modell auf dem Prozessor findet auch Stellen mit anderen Worten („Auto“ findet „Kfz“); etwa 300 MB, nur bei Bedarf.": "A small model on the processor also finds passages in other words (\"car\" finds \"vehicle\"). About 300 MB of memory, only while needed.","Originale aufbewahren": "Keep originals","Die hochgeladene Datei bleibt auf dem Spark, lässt sich wieder öffnen und kommt in die Sicherung.": "The uploaded file stays on the Spark, can be opened again and goes into the backup.","Speicher pro Profil (MB)": "Space per profile (MB)","50 bis 5000, für alle Uploads eines Profils zusammen. Einzelnen Profilen gibst du unter Zustand → Monitoring mehr oder weniger. Ist er voll, nimmt der Spark nichts Neues an; Originale nur, solange Platz ist.": "50 to 5000, for all uploads of a profile together. Under Zustand → Monitoring you give single profiles more or less. When it is full, the Spark takes nothing new; originals only while there is room.","PDF bis 100 MB (der Admin kann mehr erlauben); Word, Excel, PowerPoint, OpenDocument, Text, Markdown, HTML, CSV oder E-Mail (.eml) je bis 20 MB. Der Assistent sucht darin, wenn eine Frage dazu passt. Nur du kannst sie nutzen, außer du gibst ein Dokument „Für alle“ frei.": "PDF up to 100 MB (the admin may allow more); Word, Excel, PowerPoint, OpenDocument, text, Markdown, HTML, CSV or e-mail (.eml) up to 20 MB each. The assistant searches them when a question fits. Only you can use them, unless you share a document \"For everyone\".","Suche ausprobieren, z. B. Kündigungsfrist": "Try the search, e.g. notice period","Suchen": "Search","bekommen nur Websuche und Gedächtnis (Antwort beginnt früher)": "get only web search and memory (answer starts sooner)","Schneller Antwortbeginn": "Faster answer start","Die Uhrzeit geht mit der Frage mit. So liest das Sprachmodell Anweisung, Werkzeuge und Verlauf aus seinem Zwischenspeicher.": "The time goes along with the question. The language model then reads instructions, tools and history from its cache.","Wirkt, wenn der Sprachmodell-Server Präfix-Caching nutzt (bei vLLM Standard). Ob es hilft, zeigt Zustand → Logs → Erweitert → Gespräch: pro Antwort steht dort, wie viele Tokens gelesen wurden und wie viele davon aus dem Zwischenspeicher kamen.": "Works when the language model server uses prefix caching (default in vLLM). Whether it helps shows under State → Logs → Advanced → Conversation: each answer lists how many tokens were read and how many came from the cache.","Raum-Modus aus der Ferne starten": "Start room mode from afar","„Raummodus im Wohnzimmer an“ lässt einen eigenen Lautsprecher zuhören, nach einem „Ja“. Braucht Lautsprecher.": "\"Raummodus im Wohnzimmer an\" lets an own speaker listen, after a \"Ja\". Needs speakers.","Diagnose": "Diagnosis","Dienste": "Services","Änderungen": "Changes","In der Ausgabe suchen …": "Search the output …","Kopieren für Thread": "Copy for thread","Live": "Live","Ansehen": "View","Hört gerade zu": "Listening right now","Alle beenden": "Stop all","Nur wo und bis wann, nie was gehört wurde.": "Only where and until when, never what was heard.","Raum-Modus für Home Assistant": "Room mode for Home Assistant","Profile dürfen einen Schlüssel anlegen, mit dem Home Assistant liest, wo zugehört wird, und es beenden kann.": "Profiles may make a key with which Home Assistant reads where it listens and can end it.","Eigene Wörter pro Gruppe": "Own words per group","Kommt eines dieser Wörter in der Frage vor, gehört sie zu dieser Gruppe. Eine Zeile pro Gruppe, die Namen stehen in der Tabelle unten. Nur ganze Wörter, höchstens 20 pro Gruppe. Die eingebauten Wörter bleiben immer.": "If one of these words is in the question, it belongs to this group. One line per group, the names are in the table below. Whole words only, at most 20 per group. The built-in words always stay.","Ausprobieren": "Try it","Regeln ansehen": "Show the rules","Gezielte Werkzeugwahl": "Targeted tool choice","Feste Regeln erkennen, worum es geht; das Sprachmodell sieht nur die passenden Werkzeuge. Jedes Profil schaltet es selbst ein.": "Fixed rules recognize what it is about; the language model sees only the matching tools. Each profile switches it on for itself.","Fragen, die keine Regel erkennt": "Questions no rule recognizes","bekommen alle Werkzeuge wie bisher (empfohlen)": "get all tools as before (recommended)","ordnet das Sprachmodell kurz einer Gruppe zu (etwa eine halbe Sekunde)": "the language model sorts them into a group (about half a second)","Nachricht": "Message","Für alle Profile einschalten": "Switch on for every profile","Schaltet „Nachrichten für mich nutzen“ bei jedem Profil ein; jedes kann es unter Ich → Nachrichten wieder ausschalten. Erst nach dem Speichern des Schalters oben.": "Switches \"Use messages for me\" on for every profile; each can switch it off again under Me → Messages. Only after saving the switch above.","Nachricht an andere": "Message to others","Empfänger": "Recipient","Nachrichten an andere": "Messages to others","„Sag Anna, das Essen ist fertig“: kurze Nachrichten zwischen den Profilen dieses Sparks, gesendet erst nach „Ja“.": "\"Tell Anna dinner is ready\": short messages between the profiles of this Spark, sent only after \"Yes\".","Nachricht an alle": "Message to everybody","„Sag allen, wir fahren um acht“ an jedes Profil, das solche Nachrichten annimmt.": "\"Tell everybody we leave at eight\" to every profile that takes such messages.","Durchsagen auf Lautsprechern": "Announcements on speakers","„Durchsage im Wohnzimmer: Essen ist fertig“, nur auf Lautsprechern, deren Profil Durchsagen erlaubt.": "\"Announcement in the living room: dinner is ready\", only on speakers whose profile allows announcements.","Sprachnachrichten": "Voice messages","Bis 30 Sekunden im Browser aufnehmen; die Spracherkennung schreibt den Text dazu.": "Record up to 30 seconds in the browser; the speech recognition adds the text.","Bild": "Picture","Bilder erkennen": "Picture recognition","Profile hängen im Assistenten, in der iPhone-App oder über Telegram ein Foto an; das Sprachmodell (qwen38) sieht es sich selbst an.": "Profiles attach a photo in the assistant, the iPhone app or over Telegram; the language model (qwen38) looks at it itself.","Prüft einmal, ob das laufende Sprachmodell Bilder annimmt: Es bekommt ein Testbild mit einer Zahl.": "Checks once whether the running language model accepts pictures: it gets a test picture with a number.","Bilderkennung prüfen": "Check picture recognition","Spark-Update über die iPhone-App": "Spark update from the iPhone app","Ausgewählte Profile erfahren in der App von neuen geprüften Versionen und dürfen das Update dort starten.": "Chosen profiles learn about new tested versions in the app and may start the update there.","Wer was darf, legst nur du hier fest. Starten geht nur mit dem zweiten Anmeldeschritt des Profils: Face ID und ein frischer Code aus der Authenticator-App. Installiert werden nur Stände mit grünen GitHub-Tests.": "Only you decide here who may do what. Starting needs the profile's second login step: Face ID and a fresh code from the authenticator app. Only versions with green GitHub tests are installed.","Agent-Funktionen": "Agent functions","„Recherchiere …, sag mir Bescheid“: Aufträge im Hintergrund, geplante Aufträge und eigene Abläufe, nur für freigeschaltete Profile.": "\"Research …, let me know\": background jobs, scheduled jobs and own routines, only for profiles that were allowed.","Dienste per MCP": "Services over MCP","Werkzeuge fremder Dienste (Paperless, Nextcloud …), jedes einzeln freigegeben.": "Tools of outside services (Paperless, Nextcloud …), each allowed one by one.","KI-Agenten: Hermes und OpenClaw": "AI agents: Hermes and OpenClaw","Ein Agent wie Hermes Agent (Nous Research) oder OpenClaw kann mit dieser Spark hören und sprechen: Spracherkennung und Sprachausgabe laufen hier, der Agent selbst läuft woanders. Er bekommt nur Audio und den Text zum Vorlesen, keinen Zugang zu Profilen, Gedächtnis oder Werkzeugen des Assistenten.": "An agent such as Hermes Agent (Nous Research) or OpenClaw can listen and speak with this Spark: speech recognition and speech output run here, the agent itself runs elsewhere. It only gets audio and the text to read out, no access to the assistant's profiles, memory or tools.","Ergänzen in": "Add to",", dann den Agenten neu starten.": ", then restart the agent.","In der OpenClaw-Konfiguration ergänzen. Den Schlüssel für die Spracherkennung als OpenAI-API-Key-Profil hinterlegen.": "Add to the OpenClaw configuration. Store the key for speech recognition as an OpenAI API key profile.","Läuft der Agent auf einem anderen Rechner, die LAN-IP der Spark nehmen. Ohne API-Schlüssel (Einstellungen → Sicherheit) kann jeder im Heimnetz die Sprachdienste nutzen. Den Agenten nicht auf dieser Spark installieren: Er führt selbst Befehle aus und käme so an Einstellungen und Schlüssel.": "If the agent runs on another computer, use the Spark's LAN IP. Without an API key (Settings → Security) anyone on the home network can use the speech services. Do not install the agent on this Spark: it runs commands itself and could reach settings and keys.","Eigene Stimme überhören": "Ignore my own voice","Hört ein Gerät die Antwort eines anderen Geräts (Lautsprecher, iPhone), nimmt der Assistent sie nicht als neue Frage.": "When a device hears another device's answer (speaker, iPhone), the assistant does not take it as a new question.","Was er überhört": "What it ignores","Sätze, die er gerade selbst gesagt hat": "Sentences it just said itself","dazu alles, solange ein anderes Gerät spricht (empfohlen)": "also everything while another device is speaking (recommended)","Stellt dem echten Sprachmodell 20 feste Fragen, die meisten in drei Formulierungen, und prüft Werkzeug und Antwort. Echte Daten werden dabei weder gelesen noch geändert.": "Asks the real language model 20 fixed questions, most of them in three wordings, and checks tool and answer. Real data is neither read nor changed.","Wie geprüft wird": "How it checks","Die Werkzeuge liefern vorbereitete Ergebnisse (Termine, Mails, Erinnerungen, Suche, Gedächtnis, „weiß ich nicht“-Fälle). Geprüft wird, ob das Modell das richtige Werkzeug nimmt und was du nach der Antwort-Prüfung hörst. Ein Fehlschlag läuft einmal neu; der Verlauf zeigt neu kaputte und wackelnde Fragen. Läuft nach jedem Update von selbst, dauert zwei bis vier Minuten.": "The tools return prepared results (appointments, mail, reminders, search, memory, “don't know” cases). It checks whether the model picks the right tool and what you hear after the answer check. A failure runs once more; the history shows newly broken and wobbly questions. Runs by itself after every update and takes two to four minutes.","Push an die iPhone-App": "Push to the iPhone app","Meldungen kommen auch bei geschlossener App. Apple sieht nur „Neue Nachricht“, den Text holt die App vom Spark.": "Notifications arrive with the app closed too. Apple only sees \"New message\"; the app fetches the text from the Spark.","Schlüssel von developer.apple.com → Certificates, IDs & Profiles → Keys → „+“ → Apple Push Notifications service (APNs). Die .p8-Datei gibt es nur einmal zum Herunterladen.": "Key from developer.apple.com → Certificates, IDs & Profiles → Keys → \"+\" → Apple Push Notifications service (APNs). The .p8 file can be downloaded only once.","Schlüsseldatei (.p8)": "Key file (.p8)","Bundle-ID der App": "The app's bundle ID","Art der App": "Kind of app","Entwicklung (direkt aus Xcode)": "Development (straight from Xcode)","Produktion (TestFlight, App Store)": "Production (TestFlight, App Store)","Schlüssel löschen": "Delete key","Gesicht des Assistenten": "Assistant's face","Roboter": "Robot","Comic": "Comic","Gilt für alle: Assistent, schwebender Knopf und iPhone-App.": "Applies to everybody: assistant, floating button and iPhone app.","iPhone-App": "iPhone app","Profile koppeln die App „Spark“ auf ihrem iPhone: fragen und hören mit der Spark-Stimme, auch per Siri.": "Profiles pair the \"Spark\" app on their iPhone: ask and listen in the Spark voice, also through Siri.","Braucht dich": "Needs you","Zustand wird geladen …": "Loading status …","Zustand": "Status","Profile und Geräte": "Profiles and devices","Spark verwalten": "Manage Spark","Ich": "Me","Verwalten": "Manage","Diagnose-Filter": "Diagnostic filters","Lautsprecher (esp32)": "Speakers (esp32)","Update und Selbsttest": "Update and self-test","Fehler": "Errors","letzte 10 min": "last 10 min","letzte Stunde": "last hour","letzte 2 Stunden": "last 2 hours","letzte 12 Stunden": "last 12 hours","letzte 24 Stunden": "last 24 hours","30 Zeilen": "30 lines","100 Zeilen": "100 lines","300 Zeilen": "300 lines","1000 Zeilen": "1000 lines","Wie journalctl … | grep … | tail auf der Konsole. Nichts angehakt = alle Zeilen. „Kopieren“ und in den Thread einfügen.": "Like journalctl … | grep … | tail on the console. Nothing ticked = all lines. Use “Copy” and paste it into the thread.","Eigene Stimmen für die Sprachausgabe: aufnehmen, anhören, sichern. Welche Stimme der Assistent nutzt, steht unter Sprachausgabe → Standardstimme; jedes Profil kann sich unter Ich → Gespräch eine andere wählen. Wer spricht, erkennt dagegen die Sprechererkennung.": "Your own voices for speech output: record, listen, back up. Which voice the assistant uses is set under Speech output → Default voice; each profile can pick another under Me → Conversation. Who is speaking is a different thing: that is speaker identification.","Eigener Gesprächsstil": "Own conversation style","Rückfrage ohne Weckwort": "Follow-up without wake word","Nach der Antwort auf eine gesprochene Frage hört der Assistent ein paar Sekunden weiter zu; jedes Profil wählt die Dauer.": "After answering a spoken question the assistant keeps listening for a few seconds; each profile picks the time.","Standard wiederherstellen": "Restore default","Ganzen Prompt ansehen": "Show the whole prompt","Erweitert": "Advanced","Verlaufslänge (Zeichen)": "History length (characters)","Wie viel vom bisherigen Gespräch das Modell mitbekommt, 4000 bis 64000. 24000 sind etwa 8000 Tokens. Mehr braucht ein Modell mit großem Kontextfenster und mehr Speicher.": "How much of the conversation so far the model gets, 4000 to 64000. 24000 is about 8000 tokens. More needs a model with a large context window and more memory.","Websuchen pro Antwort": "Web searches per answer","1 bis 3. Mehr ist gründlicher, aber langsamer.": "1 to 3. More is more thorough, but slower.","Zeitlimit für eine Antwort (Sekunden)": "Time limit for an answer (seconds)","60 bis 600. Kürzer lohnt sich, wenn das Modell auf einem anderen Rechner läuft und dort hängen kann.": "60 to 600. Shorter is worth it when the model runs on another computer and can hang there.","0 = Standard des Servers. Sonst 0.05 bis 1; kleiner = vorsichtigere Wortwahl.": "0 = the server's default. Otherwise 0.05 to 1; smaller = more careful word choice.","0 = Standard des Servers. Bis 2; hilft, wenn das Modell sich wiederholt (Qwen empfiehlt dann etwa 1).": "0 = the server's default. Up to 2; helps when the model repeats itself (Qwen then recommends about 1).","Eigene Stichwörter für die Werkzeugpflicht": "Own keywords that require a tool","Kommt eines dieser Wörter in der Frage vor, muss das Modell zuerst das Werkzeug benutzen. Eine Zeile pro Werkzeug: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Nur ganze Wörter, höchstens 20 pro Werkzeug. Die eingebauten Wörter bleiben immer.": "If one of these words is in the question, the model must use the tool first. One line per tool: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Whole words only, at most 20 per tool. The built-in words always stay.","Aus Korrekturen lernen": "Learning from corrections","Fragen aus Korrekturen": "Questions from corrections","Profile haben sie nach einer Korrektur übergeben. Sie laufen bei jedem Test mit; jedes Werkzeug findet dabei nichts, das Modell darf also nichts erfinden.": "Profiles handed them over after a correction. They run with every test; every tool finds nothing, so the model must not make anything up.","Temperatur bei der Werkzeugwahl": "Temperature when choosing tools","Gilt, solange das Modell entscheidet, welches Werkzeug es nimmt; danach gilt die Temperatur oben. 0.1 empfohlen.": "Used while the model decides which tool to take; after that the temperature above applies. 0.1 recommended.","Antwort-Prüfung": "Answer check","Bei Fragen nach Terminen, Mails, Erinnerungen, Ergebnissen usw. sagt der Assistent keine Uhrzeit, kein Datum, keinen Spielstand und keinen Betrag, der in keinem Werkzeug-Ergebnis steht. Antwortet das Modell ohne nachzusehen, wird es einmal neu gefragt. Empfohlen: an.": "For questions about appointments, mail, reminders, results and so on, the assistant says no time, date, score or amount that is in no tool result. If the model answers without looking anything up, it is asked once more. Recommended: on.","Profile dürfen bei der Werkzeugwahl nachdenken": "Profiles may think while choosing tools","Jedes Profil schaltet es unter Ich → Gespräch selbst ein. Das Modell denkt dann nur, während es das Werkzeug wählt: zuverlässiger, aber die Antwort beginnt später. Nie für Gäste.": "Each profile switches it on itself under Me → Conversation. The model then thinks only while choosing the tool: more reliable, but the answer starts later. Never for guests.","Heimnetz": "Home network","Heimnetz-Adressen für Kalender, Kontakte und Mail erlauben": "Allow home network addresses for calendars, contacts and mail","Aus: Kalender, Adressbücher, Aufgaben und Postfächer der Profile dürfen nur auf Adressen im Internet liegen (z. B. iCloud, GMX). An: auch Server im Heimnetz (z. B. ein NAS). Home Assistant darf immer im Heimnetz liegen. Die Dienste des Sparks selbst und Adressen wie 169.254.x sind nie erreichbar.": "Off: profile calendars, address books, task lists and mailboxes may only be on internet addresses (e.g. iCloud, GMX). On: also servers in the home network (e.g. a NAS). Home Assistant may always be in the home network. The Spark's own services and addresses like 169.254.x are never reachable.","Admin-Anmeldung": "Admin login","Admin überall abmelden": "Log the admin out everywhere","Beendet die Admin-Anmeldung in allen Browsern, auch in diesem (z. B. nach einem verlorenen Gerät).": "Ends the admin login in every browser, this one too (e.g. after a lost device).","Nur von diesen Adressen wird die weitergereichte Absender-Adresse (X-Forwarded-For) geglaubt, z. B. 192.168.1.10. Leer = nur ein Proxy auf dem Spark selbst. Eintragen, wenn das Panel hinter einem Proxy im Heimnetz hängt: sonst teilen sich alle, die über den Proxy kommen, eine Adresse für die Sperre nach falschen Passwörtern.": "Only from these addresses is the forwarded sender address (X-Forwarded-For) believed, e.g. 192.168.1.10. Empty = only a proxy on the Spark itself. Enter it when the panel sits behind a proxy in the home network: otherwise everyone coming through the proxy shares one address for the lock after wrong passwords.","Adresse von Home Assistant übernehmen": "Take the Home Assistant address","Bus und Bahn": "Bus and train","Adresse des Fahrplandienstes": "Timetable service address","Leer = v6.db.transport.rest. Auch ein eigener db-rest oder ein regionaler Dienst (z. B. v6.vbb.transport.rest).": "Empty = v6.db.transport.rest. Also an own db-rest or a regional service (e.g. v6.vbb.transport.rest).","Home Assistant Assist (Wyoming)": "Home Assistant Assist (Wyoming)","Erlaubte Adressen": "Allowed addresses","Die Adresse deines Home Assistant, mehrere mit Komma, auch Netze wie 192.168.1.0/24. Leer = niemand.": "Your Home Assistant's address, several with commas, also networks like 192.168.1.0/24. Empty = nobody.","Aufgaben und Einkaufsliste": "Tasks and shopping list","Telegram": "Telegram","Bot-Token von @BotFather (Anleitung über den Knopf „Anleitung“).": "Bot token from @BotFather (see the \"Guide\" button).","Token löschen": "Delete token","Wetter": "Weather","Kontakte": "Contacts","Pakete": "Parcels","Wetter (Open-Meteo)": "Weather (Open-Meteo)","Adresse der Vorhersage": "Forecast address","Adresse der Ortssuche": "Place search address","Nur ändern, wenn du Open-Meteo selbst betreibst.": "Only change this if you run Open-Meteo yourself.","Alle Anleitungen": "All guides","Zu jedem Dienst, den man einschalten kann: was er kann, was du brauchst, wie du ihn einrichtest und benutzt, was das Haus verlässt und wie du ihn wieder ausschaltest. Dieselbe Anleitung steht auch neben dem Schalter unter Einstellungen → Funktionen und im Ich.": "For every service you can switch on: what it does, what you need, how to set it up and use it, what leaves the house and how to switch it off again. The same guide is also next to its switch under Settings → Features and in the Me.","Postfach aufräumen": "Inbox tidying","Alle Einstellungen": "All settings","Adressen des Reverse-Proxys": "Reverse proxy addresses","Nur von diesen Adressen wird die weitergereichte Absender-Adresse (X-Forwarded-For) geglaubt, z. B. 192.168.1.10. Leer = von jedem Gerät im Heimnetz. Eintragen, wenn das Panel hinter einem Proxy hängt: dann kann kein anderes Gerät im Netz die Sperre nach falschen Passwörtern umgehen.": "The forwarded sender address (X-Forwarded-For) is only believed from these addresses, e.g. 192.168.1.10. Empty = from any device in the LAN. Fill in when the panel sits behind a proxy: then no other device in the network can get around the lockout after wrong passwords.","Raum-Modus": "Room mode","Fernsehstimmen überhören": "Ignore TV voices","Jedes Gerät kann wählen, nur bekannten Stimmen zuzuhören (Sprechererkennung), z. B. solange der Fernseher läuft (Home Assistant).": "Each device can choose to listen only to known voices (speaker identification), e.g. while the TV is on (Home Assistant).","Raum": "Room","Erkennung": "Recognizer","Qwen3-ASR (Grafikkarte)": "Qwen3-ASR (GPU)","Parakeet Deutsch (Prozessor)": "Parakeet German (CPU)","Parakeet (primeline, deutsch nachtrainiert) läuft auf dem Prozessor, braucht etwa 1 GiB statt mehrerer GiB und ist sehr schnell, kennt aber keinen Kontext und versteht vor allem Deutsch. Beim Umschalten startet die Spracherkennung neu; beim ersten Mal lädt Parakeet etwa 640 MB herunter.": "Parakeet (primeline, fine-tuned for German) runs on the CPU, needs about 1 GiB instead of several and is very fast, but ignores the context and mainly understands German. Switching restarts speech recognition; the first time Parakeet downloads about 640 MB.","Von selbst melden": "Speak up by itself","Aufräumen vorschlagen": "Propose cleanup","Einmal pro Woche schlägt der Assistent vor, doppelte oder überholte Einträge zusammenzufassen. Es ändert sich erst etwas, wenn du hier bestätigst.": "Once a week the assistant proposes merging duplicate or outdated entries. Nothing changes until you confirm here.","Qualitätstest": "Quality test","Stellt dem echten Sprachmodell 20 feste Fragen, die meisten zusätzlich in zwei anderen Formulierungen, mit vorbereiteten Werkzeug-Ergebnissen (Termine, Mails, Erinnerungen, Suche, Gedächtnis, „weiß ich nicht“-Fälle). Geprüft wird, ob es das richtige Werkzeug nimmt und was du nach der Antwort-Prüfung hörst. Ein Fehlschlag läuft einmal neu; der Verlauf zeigt neu kaputte und wackelnde Fragen. Echte Daten werden dabei weder gelesen noch geändert. Läuft nach jedem Update von selbst, dauert zwei bis vier Minuten.": "Asks the real language model 20 fixed questions, most of them also in two other wordings, with prepared tool results (appointments, mail, reminders, search, memory, \"I don't know\" cases). It checks that the model picks the right tool and what you hear after the answer check. A failure runs once more; the history shows newly broken and wobbly questions. No real data is read or changed. Runs by itself after every update and takes two to four minutes.","Tagesbriefing als Mitteilung": "Daily briefing as a notification","Aus": "Off","Jeden Morgen zu dieser Uhrzeit: Termine, Erinnerungen, ungelesene Mails und deine Themen, kurz zusammengefasst. Kommt auf alle Geräte mit eingeschalteten Mitteilungen und steht danach auch im Verlauf.": "Every morning at this time: appointments, reminders, unread mail and your topics in short. Goes to every device with notifications on and is kept in the history too.","Neu laden": "Reload","Protokoll leeren": "Clear log","E-Mail lesen": "Read e-mail","Frag „Hab ich neue Mails?“, „Was schreibt Anna?“ oder „Lies mir die Mail von der Telekom vor“. Der Assistent liest nur den Posteingang der letzten 30 Tage und ändert nichts: keine Mail wird gesendet, gelöscht oder als gelesen markiert. Das Passwort bleibt verschlüsselt auf dem Spark.": "Ask \"Any new mail?\", \"What does Anna write?\" or \"Read me the mail from the bank\". The assistant only reads the inbox of the last 30 days and changes nothing: no mail is sent, deleted or marked as read. The password stays encrypted on the Spark.","Postfach hinzufügen": "Add mailbox","anderer IMAP-Server": "other IMAP server","z. B. Privat": "e.g. Personal","Postfächer prüfen": "Check mailboxes","Codewort für Änderungen": "Code word for changes","Ist eines gesetzt, schaltet der Assistent erst, wenn du es in derselben Nachricht sagst, z. B. „Licht aus, Codewort Sonnenblume“. Abfragen gehen ohne. Nimm ein Wort, das die Spracherkennung sicher versteht. Leer speichern entfernt es.": "When one is set, the assistant switches only when you say it in the same message, e.g. \"Lights off, code word sunflower\". Questions work without it. Pick a word the speech recognition gets right. Saving it empty removes it.","Funktionen": "Features","Nutzer": "Users","Profile": "Profiles","Übersicht": "Overview","Websuche": "Web search","Was der Assistent können soll. Tippe auf eine Funktion für Erklärung und Einstellungen.": "What the assistant should be able to do. Tap a feature for its explanation and settings.","Zugang zum Assistenten": "Access to the assistant","Unter": "Under","beim eigenen Profil ein Gerät „Pebble“ anlegen und den Schlüssel kopieren.": "add a device \"Pebble\" to your own profile and copy the key.","Über deine eigene SearXNG-Instanz. Am besten erlaubt sie das JSON-Format (settings.yml: search.formats: [html, json]); sonst liest das Panel die normale Ergebnisseite.": "Through your own SearXNG instance. Best let it allow the JSON format (settings.yml: search.formats: [html, json]); otherwise the panel reads the normal results page.","Wetter Berlin, Nachrichten": "Weather Berlin, news","Wie warm ist es im Wohnzimmer?": "How warm is it in the living room?","z. B. Arbeit": "e.g. Work","Deutsch": "German","An: Startseite für alle im Netz, auch Gäste. Aus: nur angemeldete Profile (Name und PIN) und Geräte mit Schlüssel, keine Gäste. Einstellungen bleiben immer geschützt.": "On: start page for everyone on the network, guests included. Off: only signed-in profiles (name and PIN) and devices with a key, no guests. Settings always stay protected.","Der Assistent ist nur für Profile freigegeben. Bitte melde dich mit Name und PIN an.": "The assistant is open to profiles only. Please sign in with name and PIN.","Verbinde dein Home Assistant, dann sagst du „Mach das Licht im Wohnzimmer an“ oder „Wie warm ist es im Bad?“. Nur dein Profil kann es nutzen. Der Assistent sieht alle Geräte, Zonen und Personen, die dein Home-Assistant-Benutzer sehen darf; Schlösser, Alarmanlage und Updates schaltet er nie. Der Token bleibt auf dem Spark.": "Connect your Home Assistant, then say \"Turn on the living room light\" or \"How warm is it in the bathroom?\". Only your profile can use it. The assistant sees every device, zone and person your Home Assistant user may see; it never switches locks, alarm systems or updates. The token stays on the Spark.","Langlebiger Zugriffstoken": "Long-lived access token","In Home Assistant: dein Profil → Sicherheit → Langlebige Zugriffstoken → Token erstellen. Am besten für einen eigenen Benutzer ohne Admin-Rechte.": "In Home Assistant: your profile → Security → Long-lived access tokens → Create token. Best for a separate user without admin rights.","Zertifikat nicht prüfen (selbst signiertes HTTPS)": "Don't verify the certificate (self-signed HTTPS)","Assist-Agent (leer = Standard)": "Assist agent (empty = default)","Prüfen und speichern": "Check and save","Trennen": "Disconnect","Frühere Gespräche": "Earlier conversations","Update läuft": "Update running","Starte …": "Starting …","Bitte warten. Bis das Update fertig ist, sind Änderungen gesperrt. Die Seite lädt danach von selbst neu.": "Please wait. Changes are locked until the update has finished. The page then reloads by itself.","Anbieter": "Provider","anderer CalDAV-Server": "other CalDAV server","Abo-Link (webcal://, webcals://, .ics, Google)": "Subscription link (webcal://, webcals://, .ics, Google)","„Guten Morgen“ oder „Was steht heute an?“: Der Assistent liest Termine, Erinnerungen und deine Themen vor. Du kannst mehrere Kalender verbinden. „Trag Zahnarzt Dienstag 10 Uhr ein“ legt einen Termin im ersten CalDAV-Kalender an, aber erst, wenn du den Vorschlag mit Ja bestätigst; Abo-Links bleiben nur lesend.": "\"Good morning\" or \"What's on today?\": the assistant reads out appointments, reminders and your topics. You can connect several calendars. \"Put dentist on Tuesday 10 am\" adds an appointment to the first CalDAV calendar, but only after you confirm the proposal with yes; subscription links stay read only.","CalDAV-Adresse (Nextcloud, iCloud, Radicale …) mit Benutzer und App-Passwort, oder ein iCal-Abo-Link ohne Benutzer (Google: „Privatadresse im iCal-Format“). Das Passwort bleibt auf dem Spark.": "A CalDAV address (Nextcloud, iCloud, Radicale …) with user and app password, or an iCal subscription link without user (Google: \"Secret address in iCal format\"). The password stays on the Spark.","Gedächtnis": "Memory","Dokumente": "Documents","Kalender": "Calendar","Kalender hinzufügen": "Add calendar","Adresse": "Address","Prüfen und hinzufügen": "Check and add","Themen fürs Briefing (höchstens drei, mit Komma getrennt)": "Briefing topics (at most three, separated by commas)","Nächste Termine zeigen": "Show next appointments","Zurück zum Gesicht": "Back to the face","Kalender und Tagesbriefing": "Calendar and daily briefing","Kalender-Adresse": "Calendar address","Benutzer": "User","Passwort": "Password","Themen fürs Briefing (je Zeile eines, höchstens drei)": "Briefing topics (one per line, at most three)","Die Themen sucht der Assistent über die Websuche.": "The assistant looks the topics up with the web search.","Speichern und testen": "Save and test","Kalender entfernen": "Remove calendar","sehr schnell: erster Ton am frühesten, kann bei voller GPU stocken": "very fast: earliest first audio, may stutter when the GPU is busy","Nochmal vorlesen": "Read again","Start der Sprachausgabe": "Speech output start","sehr schnell: erster Ton am frühesten, Anfang kann stocken": "very fast: earliest first audio, the start may stutter","schnell": "fast","ausgewogen (empfohlen)": "balanced (recommended)","ruhig: erster Ton etwas später, läuft sehr gleichmäßig an": "calm: first audio a little later, starts very smoothly","sehr ruhig: erster Ton spürbar später": "very calm: first audio noticeably later","automatisch: vllm-omni entscheidet nach Auslastung": "automatic: vllm-omni decides by load","Die Sprachausgabe liefert den Ton in Blöcken. Ein kleiner erster Block ist früher hörbar, ein größerer läuft gleichmäßiger an; danach werden die Blöcke stufenweise größer, damit die Wiedergabe nicht abreißt. Eine Änderung startet die Sprachausgabe neu, das dauert ein paar Minuten.": "Speech output delivers audio in blocks. A small first block is audible sooner, a larger one starts more smoothly; after that the blocks grow step by step so playback does not break off. Changing it restarts speech output, which takes a few minutes.","Weitere Aufnahmen": "More recordings","Sprechererkennung": "Speaker identification","Strenge der Sprechererkennung": "Strictness of speaker identification","locker (erkennt öfter, verwechselt eher)": "loose (recognizes more often, mixes up more easily)","normal": "normal","streng (verwechselt kaum, erkennt seltener)": "strict (hardly mixes up, recognizes less often)","Meine Stimme": "My voice","Lies drei kurze Sätze vor. Danach erkennt der Assistent dich an der Stimme, auch an anderen Geräten, und antwortet mit deinem Gedächtnis, deinen Dokumenten und Einstellungen.": "Read three short sentences aloud. Then the assistant recognizes you by your voice, on other devices too, and answers with your memory, documents and settings.","Stimme einlernen": "Enroll voice","Stimme löschen": "Delete voice","Die Sprachausgabe kam nicht schnell genug nach": "Speech output fell behind","Timer und Erinnerungen": "Timers and reminders","Neues Gespräch": "New conversation","Gesprächs-Einstellungen": "Conversation settings","Hell / Dunkel": "Light / dark","Abmelden": "Log out","Meine Dokumente": "My documents","PDF, Word, Text, Markdown, HTML oder CSV, je bis 20 MB. Der Assistent sucht darin, wenn eine Frage dazu passt. Nur du kannst sie nutzen.": "PDF, Word, text, Markdown, HTML or CSV, up to 20 MB each. The assistant searches them when a question fits. Only you can use them.","Dokument hinzufügen …": "Add document …","Dokumente für Profile erlauben": "Allow documents for profiles","0 bis 5; mehr ist genauer, aber langsamer.": "0 to 5; more is more accurate, but slower.","1 bis 10.": "1 to 10.","1.7B erkennt genauer, braucht aber mehr Speicher.": "1.7B recognizes more accurately but needs more memory.","Adresse deiner SearXNG-Instanz": "Address of your SearXNG instance","Anteil am ganzen 128-GB-Pool, z. B. 0.04 ≈ 4,8 GiB.": "Share of the whole 128 GB pool, e.g. 0.04 ≈ 4.8 GiB.","Anteil am ganzen 128-GB-Pool; 1.7B: 0.06 ≈ 7,2 GiB, 0.6B: 0.035 ≈ 4,2 GiB.": "Share of the whole 128 GB pool; 1.7B: 0.06 ≈ 7.2 GiB, 0.6B: 0.035 ≈ 4.2 GiB.","Assistent": "Assistant","Assistent ohne Passwort": "Assistant without password","Aufbewahren, in Tagen": "Keep, in days","Ausrufezeichen werden zu Punkten, „Oh“, „Wow“, „Hm“ am Satzanfang fallen weg.": "Exclamation marks become full stops, \"Oh\", \"Wow\", \"Hm\" at the start of a sentence are dropped.","Aussprache": "Pronunciation","Bei qwen38 steht er in ~/.config/qwen38/api-key; das Update übernimmt ihn automatisch.": "With qwen38 it is in ~/.config/qwen38/api-key; the update imports it automatically.","DGX OS beendet Prozesse ab etwa 8 GiB freiem Speicher.": "DGX OS kills processes below about 8 GiB of free memory.","Das Mikrofon braucht https; 0 = aus.": "The microphone needs https; 0 = off.","Das Modell kennt sie sonst nicht.": "The model does not know them otherwise.","Datum und Uhrzeit mitgeben": "Pass date and time","Ein Modell wird nicht geladen, wenn danach weniger als die Reserve frei bliebe.": "A model is not loaded if less than the reserve would stay free.","Eine Regel pro Zeile, „Wort = so gesprochen“; gilt für ganze Wörter, Groß-/Kleinschreibung egal.": "One rule per line, \"word = spoken like this\"; whole words, case does not matter.","Eine feste Sprache erkennt kurze Sätze besser als „auto“.": "A fixed language recognizes short sentences better than \"auto\".","Emojis, Markdown, „haha“ und *lacht* entfernen.": "Remove emojis, markdown, \"haha\" and *laughs*.","Feste Zahl = gleiche Stimmführung über alle Sätze; -1 = zufällig.": "Fixed number = same delivery across sentences; -1 = random.","Gedächtnis für Profile": "Memory for profiles","Gelten für Gäste und für Profile, die selbst nichts geändert haben.": "Apply to guests and to profiles that changed nothing themselves.","Genauer, aber die Antwort beginnt deutlich später.": "More accurate, but the answer starts much later.","Gilt, wenn eine Anfrage keine eigene Anweisung mitbringt.": "Used when a request brings no instruction of its own.","Höchstens so viel Platz, in MB": "At most this much space, in MB","In Schritten; 4096 ≈ 5 Min. Audio, kleiner = weniger Speicher.": "In steps; 4096 ≈ 5 min of audio, smaller = less memory.","Kleiner = ruhiger und gleichmäßiger, größer = lebendiger; Qwen-Standard 0.9.": "Lower = calmer and steadier, higher = livelier; Qwen default 0.9.","Kleiner = weniger Ausreißer; Qwen-Standard 1.0.": "Lower = fewer outliers; Qwen default 1.0.","Kontext": "Context","LLM-API-Schlüssel": "LLM API key","LLM-Adresse": "LLM address","LLM-Modell": "LLM model","Leer = das erste, das der Server meldet.": "Empty = the first one the server lists.","Lädt zusätzlich den Forced Aligner (~2 GiB); nur für Untertitel und Ähnliches nötig.": "Also loads the forced aligner (~2 GiB); only needed for subtitles and the like.","Max. Länge pro Anfrage": "Max. length per request","Mindestens 10 Zeichen.": "At least 10 characters.","Namen, Fachbegriffe oder ein Satz zum Thema, die die Erkennung erwarten soll (z. B. DGX Spark, Qwen, Open WebUI).": "Names, technical terms or a sentence about the topic the recognition should expect (e.g. DGX Spark, Qwen, Open WebUI).","Neues Passwort": "New password","OpenAI-kompatibel, qwen38: http://127.0.0.1:30001/v1": "OpenAI-compatible, qwen38: http://127.0.0.1:30001/v1","Panel-Port": "Panel port","Reserve in GiB": "Reserve in GiB","Ruhig sprechen": "Speak calmly","Seiten ganz lesen": "Pages read in full","Sicherheit": "Security","Speicheranteil Talker": "Memory share talker","Speichern": "Save","Speicherschutz an": "Memory guard on","Sprachausgabe": "Speech output","Spracherkennung": "Speech recognition","Sprechstil": "Speaking style","Temperatur": "Temperature","Text bereinigen": "Clean text","Treffer pro Suche": "Results per search","VoiceDesign zusätzlich bereitstellen": "Also serve VoiceDesign","Vorgaben": "Defaults","Vorher nachdenken": "Think first","Websuche erlauben": "Allow web search","Wirkt nach einem Neustart des Panels.": "Takes effect after restarting the panel.","Wissen": "Knowledge","Zeitstempel": "Timestamps","Zweite Engine, braucht den gleichen Speicher noch einmal.": "Second engine, needs the same memory again.","Ältere Einträge werden automatisch gelöscht.": "Older entries are deleted automatically.","Ports": "Ports","HTTPS-Port": "HTTPS port","„Hey Spark“": "\"Hey Spark\"","Freihändig": "Hands-free","Auf Vorgaben zurücksetzen": "Reset to defaults","Vorgaben fürs Gespräch (für Gäste und Profile, die selbst nichts geändert haben)": "Conversation defaults (for guests and profiles that changed nothing themselves)","Dauerhaft lauschen, das Wort startet das Gespräch (Bildschirm bleibt an)": "Keep listening, the phrase starts the conversation (screen stays on)","Nach der Antwort automatisch wieder zuhören": "Listen again after each answer","PIN (mind. 4 Zeichen)": "PIN (at least 4 characters)","z. B. Lautsprecher Küche": "e.g. kitchen speaker","Gast": "Guest","Profil": "Profile","Gedächtnis für Profile: der Assistent merkt sich Dinge pro angemeldetem Profil (Gäste nie)": "Memory for profiles: the assistant remembers things per logged-in profile (never for guests)","Jedes Profil hat ein eigenes Gedächtnis und eigene Gespräche. Ein Browser meldet sich im Gespräch-Reiter mit Name und PIN an; was ein Profil weiß, sieht kein anderes und kein Gast.": "Every profile has its own memory and conversations. A browser logs in on the Talk tab with name and PIN; what one profile knows, no other profile and no guest can see.","Neues Profil": "New profile","Anlegen": "Create","Geräte": "Devices","Eigene Programme und Kurzbefehle bekommen hier einen Geräteschlüssel, das Profil wählst du in der Liste. iPhone-App, Lautsprecher, Pebble-Uhr und Home Assistant richtet jedes Profil selbst unter Ich ein: Sie bleiben fest bei diesem Profil und lassen sich hier nur löschen. Der Schlüssel geht im Header": "Your own programs and shortcuts get a device key here; pick the profile in the list. The iPhone app, speakers, Pebble watch and Home Assistant are set up by each profile itself under Me: they stay with that profile and can only be deleted here. The key goes in the header","an": "to","Neues Gerät": "New device","Profil wählen": "Choose profile","Angemeldet merkt sich der Assistent Dinge nur für dich, und deine Gespräche bleiben in deinem Profil.": "Logged in, the assistant remembers things only for you, and your conversations stay in your profile.","Name": "Name","PIN": "PIN","Das weiß der Assistent über dich. Sag ihm „Merk dir …“ oder „Vergiss …“, oder lösche hier.": "This is what the assistant knows about you. Tell it \"Remember …\" or \"Forget …\", or delete here.","Alles vergessen": "Forget everything","Schließen": "Close","Aktivierungswort „Hey Spark“: dauerhaft lauschen, das Wort startet das Gespräch (Bildschirm bleibt an)": "wake word \"Hey Spark\": keep listening, the phrase starts the conversation (screen stays on)","lauscht auf „Hey Spark“": "listening for \"Hey Spark\"","Websuche (SearXNG)": "Web search (SearXNG)","Websuche erlauben: das Modell sucht selbst, wenn eine Frage aktuelle Informationen braucht": "Allow web search: the model searches by itself when a question needs current information","Adresse deiner SearXNG-Instanz (z. B. http://192.168.1.20:8080; JSON muss in settings.yml unter search.formats erlaubt sein)": "Address of your SearXNG instance (e.g. http://192.168.1.20:8080; JSON must be allowed in settings.yml under search.formats)","Treffer pro Suche (1–10)": "Results per search (1–10)","Davon Seiten ganz lesen (0–5; mehr = genauer, aber langsamer)": "Pages read in full (0–5; more = more accurate, but slower)","Verbindung testen": "Test connection","Live-Transkript: Text schon beim Sprechen zeigen (die Antwort kommt etwas früher)": "live transcript: show the text while you speak (the answer comes a little sooner)","Dieses Gespräch löschen": "Delete this conversation","Aussprache: eine Regel pro Zeile, „Wort = so gesprochen“ (gilt für ganze Wörter, Groß-/Kleinschreibung egal)": "Pronunciation: one rule per line, \"word = spoken like this\" (whole words, case does not matter)","Datum und Uhrzeit mitgeben (das Modell kennt sie sonst nicht)": "Tell the model the date and time (it does not know them otherwise)","Exportieren und importieren": "Export and import","Eine ZIP-Datei mit Referenz-Audio und Transkript, etwa zum Sichern oder für einen anderen Spark.": "A ZIP file with reference audio and transcript, e.g. as a backup or for another Spark.","Alle exportieren": "Export all","ZIP importieren …": "Import ZIP …","gleicher Name: beide behalten": "same name: keep both","gleicher Name: ersetzen": "same name: replace","gleicher Name: überspringen": "same name: skip","Idee: Dominik Bornhäußer": "Idea: Dominik Bornhäußer","Kontext: Namen, Fachbegriffe oder ein Satz zum Thema, die die Erkennung erwarten soll (z. B. DGX Spark, Qwen, Open WebUI)": "Context: names, technical terms or a sentence about the topic the recognition should expect (e.g. DGX Spark, Qwen, Open WebUI)","Autoscroll (ans Ende springen, alle 3 s neu laden)": "Autoscroll (jump to the end, reload every 3 s)","ins Wort fallen: während der Antwort zuhören, Losreden unterbricht (am besten mit Kopfhörer oder gutem Echo-Filter)": "barge in: listen during the answer, start talking to interrupt (best with headphones or good echo cancellation)","Einstellungen": "Settings","Anmelden": "Log in","Für Einstellungen, Monitoring und Stimmen braucht es das Panel-Passwort.": "Settings, monitoring and voices need the panel password.","Abbrechen": "Cancel","Panel-Passwort": "Panel password","Aktuelles Passwort": "Current password","Neues Passwort (mindestens 10 Zeichen)": "New password (at least 10 characters)","Passwort ändern": "Change password","Assistent ohne Passwort zugänglich (Startseite für alle im Netz; Einstellungen bleiben geschützt)": "Assistant without password (start page for everyone on the network; settings stay protected)","Sprache der Stimme:": "Language of the voice:","Mit dem Mikrofon aufnehmen": "Record with the microphone","Das Mikrofon geht nur über https:": "The microphone only works over https:","Lies diesen Text ruhig und deutlich vor, so wie die Stimme später klingen soll (etwa 10 Sekunden):": "Read this text calmly and clearly, the way the voice should sound later (about 10 seconds):","Aufnahme starten": "Start recording","… oder eine Audiodatei hochladen (wav, mp3, m4a, …)": "… or upload an audio file (wav, mp3, m4a, …)","Bereit.": "Ready.","Sag etwas oder tippe unten eine Frage.": "Say something or type a question below.","Gespräch öffnen": "Open conversation","Neu": "New","Leertaste, „Sprechen“ oder ein Klick aufs Gesicht: zuhören bzw. die laufende Antwort unterbrechen.": "Space bar, \"Speak\" or a click on the face: listen, or interrupt the running answer.","Ruhig sprechen lassen (Ausrufezeichen werden zu Punkten, „Oh“, „Wow“, „Hm“ am Satzanfang fallen weg)": "Speak calmly (exclamation marks become full stops, \"Oh\", \"Wow\", \"Hm\" at the start of a sentence are dropped)","Speech auf DGX Spark": "Speech on DGX Spark","Konfiguration": "Configuration","Testen": "Test","Stimmen": "Voices","Einbinden": "Integrate","GPU-Auslastung": "GPU load","Unified Memory frei": "Unified memory free","GPU-Temperatur / Leistung": "GPU temperature / power","Speech-Dienste": "Speech services","Dienst": "Service","Modell": "Model","Anfragen": "Requests","Ø Latenz": "Avg latency","Ø erster Ton": "Avg first audio","Speicher (Torch)": "Memory (Torch)","dgx-spark-qwen38 auf dieser Box": "dgx-spark-qwen38 on this box","Speicheranteil": "Memory share","Keine qwen38-Units gefunden.": "No qwen38 units found.","GPU-Prozesse": "GPU processes","Prozess": "Process","Speicher": "Memory","Spracherkennung (ASR)": "Speech recognition (ASR)","aktiviert": "enabled","Standardsprache": "Default language","Engine (vLLM, parallel und gestreamt)": "Engine (vLLM, concurrent and streamed)","Speicheranteil (Anteil am ganzen 128-GB-Pool, 1.7B: 0.06 ≈ 7,2 GiB, 0.6B: 0.035 ≈ 4,2 GiB)": "Memory share (of the whole 128 GB pool; 1.7B: 0.06 ≈ 7.2 GiB, 0.6B: 0.035 ≈ 4.2 GiB)","Max. gleichzeitige Anfragen": "Max. concurrent requests","Max. Batchgröße": "Max. batch size","Max. neue Tokens": "Max. new tokens","Zeitstempel (lädt zusätzlich den Forced Aligner, ~2 GiB)": "Timestamps (also loads the forced aligner, ~2 GiB)","Datentyp": "Data type","Sprachausgabe (TTS)": "Speech output (TTS)","CustomVoice: feste Sprecher. VoiceDesign: Stimme per Beschreibung. Base: Stimmen klonen (Einstellungen → Stimmen).": "CustomVoice: built-in speakers. VoiceDesign: voice from a description. Base: voice cloning (Settings → Voices).","Engine (vllm-omni, gestreamt)": "Engine (vllm-omni, streamed)","Speicheranteil Talker (Anteil am ganzen 128-GB-Pool, z. B. 0.04 ≈ 4,8 GiB)": "Memory share talker (of the whole 128 GB pool, e.g. 0.04 ≈ 4.8 GiB)","Speicheranteil Code2Wav": "Memory share code2wav","Max. Länge pro Anfrage in Schritten (4096 ≈ 5 Min. Audio; kleiner = weniger Speicher)": "Max. length per request in steps (4096 ≈ 5 min of audio; smaller = less memory)","VoiceDesign zusätzlich bereitstellen (zweite Engine, gleicher Speicherbedarf noch einmal)": "Also serve VoiceDesign (second engine, needs the same memory again)","VoiceDesign-Modell": "VoiceDesign model","Standardstimme": "Default voice","Standard-Anweisung: wie gesprochen wird (gilt, wenn die Anfrage keine eigene mitbringt)": "Default instruction: how to speak (used when a request brings none)","z. B. Ruhig und freundlich, eher langsam, wie eine Hörbuchsprecherin.": "e.g. Calm and friendly, rather slow, like an audiobook narrator.","Temperatur (kleiner = ruhiger und gleichmäßiger, größer = lebendiger; Qwen-Standard 0.9)": "Temperature (lower = calmer and steadier, higher = livelier; Qwen default 0.9)","top_p (kleiner = weniger Ausreißer; Qwen-Standard 1.0)": "top_p (lower = fewer outliers; Qwen default 1.0)","Seed (feste Zahl = gleiche Stimmführung über alle Sätze; -1 = zufällig)": "Seed (fixed number = same delivery across sentences; -1 = random)","Text vor dem Sprechen bereinigen (Emojis, Markdown, „haha“, *lacht* entfernen)": "Clean text before speaking (remove emojis, markdown, \"haha\", *laughs*)","Speicherschutz": "Memory guard","Modell nicht laden, wenn danach weniger als die Reserve frei bliebe": "Do not load a model if less than the reserve would stay free","Reserve in GiB (DGX OS earlyoom greift bei ~8 GiB)": "Reserve in GiB (DGX OS earlyoom kicks in at ~8 GiB)","API-Schlüssel": "API key","Leer = APIs ohne Schlüssel erreichbar. Gesetzt = Apps müssen „Authorization: Bearer <Schlüssel>“ senden.": "Empty = APIs open without a key. Set = apps must send \"Authorization: Bearer <key>\".","Erzeugen": "Generate","Port (Änderung wirkt nach Neustart des Panels)": "Port (takes effect after restarting the panel)","Speichern und Dienste neu starten": "Save and restart services","Spracherkennung testen": "Test speech recognition","Audiodatei (wav, mp3, flac, …)": "Audio file (wav, mp3, flac, …)","Sprache": "Language","Transkribieren": "Transcribe","Sprachausgabe testen": "Test speech output","Stimme": "Voice","Anweisung (optional; bei VoiceDesign die Stimmbeschreibung)": "Instruction (optional; with VoiceDesign the voice description)","z. B. Begeistert und etwas schneller.": "e.g. Excited and a bit faster.","Modus": "Mode","Standard (konfiguriertes Modell)": "Default (configured model)","gestreamt (Ton spielt, während er erzeugt wird)": "streamed (audio plays while it is generated)","Sprechen": "Speak","Stimme zum Klonen hinzufügen": "Add a voice to clone","Nur mit einem": "Only works with a","-Modell wirksam. 5–15 Sekunden saubere Sprache; der Text sollte genau dem Gesprochenen entsprechen (leer lassen geht, klont dann schlechter).": " model. 5–15 seconds of clean speech; the text should match what is said exactly (empty works, but clones worse).","z. B. dominik": "e.g. dominik","Referenz-Audio": "Reference audio","Transkript der Referenz": "Transcript of the reference","Hinzufügen": "Add","Vorhandene Stimmen": "Existing voices","Endpunkte": "Endpoints","Beide Dienste sprechen die OpenAI-Audio-API. Jede App, die dort eine eigene „Base URL“ erlaubt, kann sie nutzen.": "Both services speak the OpenAI audio API. Any app that lets you set your own \"Base URL\" there can use them.","Admin-Panel → Einstellungen → Audio": "Admin Panel → Settings → Audio","Spracherkennung (STT)": "Speech recognition (STT)","Läuft Open WebUI in Docker auf derselben Spark, statt der IP": "If Open WebUI runs in Docker on the same Spark, use","nehmen (Container mit": "instead of the IP (start the container with","starten) oder die LAN-IP der Spark.": ") or the Spark's LAN IP.","Andere Apps": "Other apps","Überall dort, wo „OpenAI-kompatibel“ für Speech-to-Text oder Text-to-Speech auswählbar ist (z. B. LibreChat, AnythingLLM, SillyTavern, Home Assistant mit OpenAI-TTS/STT-Integration, n8n): Base URL und Schlüssel wie links eintragen. Modellname ist beliebig. Unbekannte OpenAI-Stimmen wie „alloy“ werden auf die Standardstimme umgeleitet.": "Wherever \"OpenAI-compatible\" can be chosen for speech-to-text or text-to-speech (e.g. LibreChat, AnythingLLM, SillyTavern, Home Assistant with the OpenAI TTS/STT integration, n8n): enter the base URL and key as on the left. The model name can be anything. Unknown OpenAI voices like \"alloy\" fall back to the default voice.","Formate": "Formats","TTS: mp3 (Standard), wav, flac, opus, pcm. Gestreamt mit": "TTS: mp3 (default), wav, flac, opus, pcm. Streamed with","mit base64-PCM (16 bit, mono, 24 kHz), am Ende": "with base64 PCM (16 bit, mono, 24 kHz), finally",". Pro Anfrage überschreibbar:": ". Per request you can override",". Sprechstil pro Anfrage mit": ". Speaking style per request with","(ohne Angabe gilt die Standard-Anweisung aus der Konfiguration; nur 1.7B-Modelle werten das aus). VoiceDesign mit": "(without it the default instruction from the configuration applies; only 1.7B models follow it). VoiceDesign with","und": "and",", falls eingeschaltet. STT: json, verbose_json, text. Sprache als Name („German“) oder ISO-Code („de“).": ", if enabled. STT: json, verbose_json, text. Language as a name (\"German\") or ISO code (\"de\").","Python (openai-Paket)": "Python (openai package)","Jetzt prüfen": "Check now","Update installieren": "Install update","Update abbrechen": "Cancel update","Holt den neuesten Stand von GitHub und installiert ihn. Einstellungen, Modelle und Stimmen bleiben. Vor dem Umschalten prüft ein Selbsttest die neue Version; schlägt er oder ein Schritt davor fehl, läuft die bisherige Version unverändert weiter. Geht nach dem Umschalten etwas schief, wird die bisherige Version wieder eingespielt. Während des Updates starten die Dienste kurz neu.": "Fetches the latest version from GitHub and installs it. Settings, models and voices are kept. Before the switch a self-test checks the new version; if it or an earlier step fails, the old version keeps running unchanged. If something fails after the switch, the old version is installed again. The services restart briefly during the update.","Leistung messen": "Measure performance","Misst Zeit bis zum ersten Ton, Geschwindigkeit bei einer und bei mehreren gleichzeitigen Anfragen und den Speicher der Dienste. Dauert ein bis zwei Minuten und belastet die GPU in der Zeit. Auf der Konsole:": "Measures time to first audio, speed with one and with several concurrent requests, and the memory of the services. Takes one to two minutes and loads the GPU meanwhile. On the console:","Messung starten": "Start measurement","Kopieren": "Copy","Update-Protokoll": "Update log","Aktualisieren": "Refresh","Hallo, hier spricht der DGX Spark.": "Hello, this is the DGX Spark speaking.","Zahlen vorlesen": "Reading numbers","als Wörter (Datum, Uhrzeit, Geld, Prozent; Telefonnummern in Zweierblöcken)": "as words (dates, times, money, percent; phone numbers in pairs)","in Zweierblöcken (Zahlen ab 3 Stellen: 4711 → siebenundvierzig elf)": "in pairs (numbers with 3+ digits: 4711 → forty-seven eleven)","Ziffer für Ziffer (Zahlen ab 3 Stellen: 4711 → vier sieben eins eins)": "digit by digit (numbers with 3+ digits: 4711 → four seven one one)","unverändert (das Modell rät)": "unchanged (the model guesses)","Datum, Uhrzeit, Geldbeträge und Kommazahlen werden immer ausgeschrieben, außer bei „unverändert“. Gilt für Deutsch und Englisch.": "Dates, times, amounts of money and decimals are always written out, except with \"unchanged\". Works for German and English.","Gespräch": "Talk","Der Browser erlaubt das Mikrofon nur über https. Öffne das Panel über": "The browser only allows the microphone over https. Open the panel at","und bestätige einmal die Zertifikatswarnung (das Zertifikat ist selbst erstellt). Tippen geht auch hier.": "and accept the certificate warning once (the certificate is self-signed). Typing works here too.","Stopp": "Stop","freihändig: nach der Antwort automatisch wieder zuhören": "hands-free: listen again after each answer","Aufnahme bei Stille automatisch beenden": "stop recording automatically on silence","Leertaste oder „Sprechen“: zuhören bzw. die laufende Antwort unterbrechen und neu fragen.": "Space bar or \"Speak\": listen, or interrupt the running answer and ask again.","oder hier tippen und Enter drücken": "or type here and press Enter","Senden": "Send","Verlauf": "Conversation","HTTPS-Port für den Sprach-Chat (Mikrofon braucht https; 0 = aus)": "HTTPS port for the voice chat (the microphone needs https; 0 = off)","Sprach-Chat (LLM)": "Voice chat (LLM)","LLM-Adresse (OpenAI-kompatibel, qwen38: http://127.0.0.1:30001/v1)": "LLM address (OpenAI-compatible, qwen38: http://127.0.0.1:30001/v1)","LLM-API-Schlüssel (qwen38: ~/.config/qwen38/api-key)": "LLM API key (qwen38: ~/.config/qwen38/api-key)","LLM-Modell (leer = das erste, das der Server meldet)": "LLM model (empty = the first one the server lists)","Systemanweisung": "System prompt","Max. Tokens pro Antwort": "Max. tokens per answer","Modell darf vorher nachdenken (genauer, aber deutlich langsamere Antwort)": "Let the model think first (more accurate, but a much slower answer)","Erster Audio-Block beim Streamen in Frames (1 Frame ≈ 0,08 s; kleiner = früherer erster Ton, unter ~6 stockt der Anfang; 0 = vllm-omni entscheidet nach Last)": "First audio block when streaming, in frames (1 frame ≈ 0.08 s; smaller = earlier first audio, below ~6 the start stutters; 0 = vllm-omni decides by load)","Höchstens so viel Platz für Logs, in MB (ältere Einträge werden automatisch gelöscht)": "At most this much space for logs, in MB (older entries are deleted automatically)","Logs so viele Tage aufbewahren": "Keep logs for this many days","Wirkt nach dem nächsten Update (System → Update) oder sudo ./install.sh.": "Takes effect after the next update (System → Update) or sudo ./install.sh.","Änderungsprotokoll": "Change log","Wo dein Profil angemeldet ist. Ein Gerät, das du nicht mehr nutzt oder verloren hast, kannst du hier sperren.": "Where your profile is signed in. A device you no longer use or have lost can be blocked here.","Geräte mit Schlüssel": "Devices with a key","Letzte Anmeldungen": "Recent sign-ins","Überall abmelden": "Log out everywhere","Meldet dein Profil in allen anderen Browsern ab; dieser bleibt angemeldet. Geräte mit Schlüssel (Lautsprecher, Uhr) sperrst du oben einzeln. Eine Anmeldung endet außerdem nach 90 Tagen ohne Nutzung.": "Logs your profile out in all other browsers; this one stays signed in. Devices with a key (speaker, watch) are blocked one by one above. A sign-in also ends after 90 days without use.","Zurück zur vorigen Version": "Back to the previous version","Funktionsprüfung": "Live check","Probiert die echten Dienste einmal aus: das Sprachmodell antwortet und ruft ein Werkzeug auf, die Websuche findet etwas (wenn an), die Sprachausgabe spricht einen Satz, die Spracherkennung versteht ihn wieder. Läuft nach jedem Update von selbst.": "Tries the real services once: the language model answers and calls a tool, web search finds something (when on), speech output says a sentence, speech recognition understands it again. Runs by itself after every update.","Sicherung": "Backup","Jetzt sichern": "Back up now","Aus Datei wiederherstellen …": "Restore from file …","Einrichtung erneut starten": "Run setup again","Warnen unter GiB frei": "Warn below GiB free","Darunter zeigt das Panel oben auf jeder Seite eine Warnung und schreibt es ins Änderungsprotokoll.": "Below this the panel shows a warning on top of every page and writes it to the change log.","Wächter": "Watchdog","Hängende Dienste automatisch neu starten": "Restart hung services automatically","Startet ASR, TTS oder eine Engine neu, wenn sie 5 Minuten nicht antwortet, 5 Minuten arbeitet, ohne eine Anfrage fertigzustellen, oder 45 Minuten lädt. Höchstens dreimal pro Stunde, jeder Neustart steht im Änderungsprotokoll.": "Restarts ASR, TTS or an engine that does not answer for 5 minutes, works for 5 minutes without finishing a request, or loads for 45 minutes. At most three times an hour; every restart is in the change log.","Frühere Gespräche durchsuchen": "Search earlier conversations","Erinnerungen auf diesem Gerät": "Reminders on this device","Einschalten": "Switch on","Ausschalten": "Switch off","Zurück": "Back","Überspringen": "Skip","Weiter": "Next","Code aus der Authenticator-App": "Code from the authenticator app","Diesem Browser 30 Tage vertrauen": "Trust this browser for 30 days","Handy nicht da? Ein Wiederherstellungscode geht auch.": "Phone not at hand? A recovery code works too.","Zweiter Anmeldeschritt": "Second login step","Gilt für die Admin-Anmeldung. Solange er an ist, geht die Anmeldung per HTTP-Basic (Skripte) nicht mehr, und Passwort ändern, Sicherung wiederherstellen, Geräteschlüssel anlegen oder umhängen und PINs ändern fragen jedes Mal nach einem Code. Notausgang ohne Handy und Codes: auf dem Spark sudo rm /var/lib/speech-spark/state/mfa-admin.json": "Applies to the admin login. While it is on, logging in with HTTP Basic (scripts) no longer works, and changing the password, restoring a backup, creating or moving device keys and changing PINs ask for a code every time. Way back in without phone and codes: on the Spark sudo rm /var/lib/speech-spark/state/mfa-admin.json","Zweiter Anmeldeschritt für Profile": "Second login step for profiles","z. B. Rosen schneiden": "e.g. pruning roses","Merkt sich Dinge, die man ihm sagt, getrennt pro Profil.": "Remembers what you tell it, separately per profile.","Profile können nach früheren Gesprächen fragen; aus ruhigen Gesprächen merkt er sich wenige Fakten.": "Profiles can ask about past conversations; from quiet ones it keeps a few facts.","Profile laden eigene Dokumente hoch, der Assistent sucht darin.": "Profiles upload their own documents and the assistant searches them.","Das Modell sucht selbst über deine SearXNG-Instanz, wenn eine Frage aktuelle Informationen braucht.": "The model searches through your SearXNG instance when a question needs current information.","„Erinnere mich in 10 Minuten an den Ofen“: Das Gerät klingelt und sagt es an.": "\"Remind me about the oven in 10 minutes\": the device rings and says it.","Termine vorlesen, nach „Ja“ eintragen, und auf „Guten Morgen“ das Tagesbriefing.": "Reads appointments, adds them after \"yes\", and gives the daily briefing on \"good morning\".","„Setz Milch auf die Einkaufsliste“: Liste auf dem Spark oder in einer CalDAV-Aufgabenliste.": "\"Put milk on the shopping list\": a list on the Spark or in a CalDAV task list.","Vorhersage für den eigenen Ort von Open-Meteo, ohne Schlüssel.": "Forecast for your own place from Open-Meteo, no key needed.","Abfahrten und Verspätungen an der eigenen Haltestelle.": "Departures and delays at your own stop.","Telefonnummern, E-Mail-Adressen und Geburtstage aus dem eigenen Adressbuch.": "Phone numbers, e-mail addresses and birthdays from your own address book.","Licht, Geräte und Heizung per Sprache, jedes Profil mit seinem eigenen Home Assistant.": "Lights, devices and heating by voice, each profile with its own Home Assistant.","Home Assistant nutzt Spracherkennung und Stimme des Spark (Voice PE, HA-App), nur von erlaubten Adressen.": "Home Assistant uses the Spark's speech recognition and voice (Voice PE, HA app), only from allowed addresses.","Neue Mails nennen und vorlesen; der Assistent sendet, löscht und markiert nie.": "Names and reads new mail; the assistant never sends, deletes or marks anything.","Werbung und Newsletter in eigene Ordner sortieren; nie löschen, nie senden, alles umkehrbar.": "Sorts ads and newsletters into their own folders; never deletes, never sends, everything can be undone.","Was heute kommt, aus den Versandmails im eigenen Postfach.": "What arrives today, from the shipping mails in your own mailbox.","Der Assistent meldet sich, wenn wirklich etwas ist: Termine, Smart-Home-Regeln, wichtige Mails, Wetter.": "The assistant speaks up when something really matters: appointments, smart home rules, important mail, weather.","Hört an einem Gerät für eine gewählte Zeit dem Gespräch im Raum zu und hilft in Pausen.": "Listens to the conversation in the room on one device for a chosen time and helps in pauses.","Profile schreiben dem Assistenten über einen eigenen Telegram-Bot, auch mit Sprachnachrichten.": "Profiles write to the assistant through their own Telegram bot, voice messages too.","ESP32-S3-Boards mit Mikrofon und Lautsprecher als Sprachassistent im Raum.": "ESP32-S3 boards with microphone and speaker as a voice assistant in the room.","Profile können bei der Anmeldung zusätzlich einen Code aus einer Authenticator-App verlangen.": "Profiles can require an extra code from an authenticator app when signing in.","Nach einer Korrektur schlägt der Assistent einen Satz zum Merken vor und speichert ihn erst nach „Ja“.": "After a correction the assistant suggests a sentence to remember and saves it only after \"yes\".","Profile sagen in eigenen Worten, wie der Assistent mit ihnen reden soll; das ändert nur den Ton, nie die Regeln.": "Profiles say in their own words how the assistant should talk to them; this changes the tone only, never the rules.","Erkennt Profile an der Stimme, auch an fremden Geräten. Eine Stimme ist kein Passwort.": "Recognises profiles by their voice, on other devices too. A voice is not a password.","Bei der Werkzeugwahl nachdenken": "Think while choosing tools","Profile können einschalten, dass das Modell vor der Werkzeugwahl nachdenkt: zuverlässiger, aber die Antwort beginnt später.": "Profiles can switch on that the model thinks before choosing a tool: more reliable, but the answer starts later.","Sprachmodell": "Language model","Betrieb": "Operation","Reverse Proxy": "Reverse proxy","Was er kann": "What it can do","Wie er denkt und spricht": "How it thinks and speaks","Spark selbst": "The Spark itself","Erinnerungen und das Tagesbriefing kommen als Mitteilung aufs Handy oder den Rechner, auch wenn die Seite zu ist.": "Reminders and the daily briefing arrive as a notification on your phone or computer, even when the page is closed.","Profile (Gedächtnis, Gespräche, Dokumente, Kalender, E-Mail-Konten, Smart Home, Stimmerkennung), geklonte Stimmen, Einstellungen, Panel-Passwort und was der Spark für alle hält (zweiter Anmeldeschritt des Admins, iPhone-Push, Telegram-Bot, Browser-Push, ESP32-Lautsprecher, Agent-Dienste, eigene Testfragen). Jeden Tag automatisch, die letzten sieben bleiben; dazu vor jedem Update, jeder Rückkehr zur vorigen Version und jedem Wiederherstellen, davon bleiben die letzten fünf.": "Profiles (memory, conversations, documents, calendars, mail accounts, smart home, speaker recognition), cloned voices, settings, panel password and what the Spark keeps for everyone (the admin's second login step, iPhone push, Telegram bot, browser push, ESP32 speakers, agent services, own test questions). Automatically every day, the last seven are kept; plus before every update, every return to the previous version and every restore, of which the last five are kept.","Gespeicherte Passwörter, Tokens und Schlüssel lassen sich mit einer normalen Sicherung nur auf diesem Spark lesen; auf einem anderen müssen sie neu eingegeben werden. Eine Umzugs-Sicherung bringt den Schlüssel dafür mit, verschlüsselt mit deinem Passwort: Auf dem neuen Spark dasselbe Passwort ins Feld eintragen, dann wiederherstellen. Anmelden muss sich danach jeder neu. Beim Wiederherstellen werden die Einstellungen wie auf der Einstellungsseite geprüft, und es wird alles getauscht oder nichts.": "With a normal backup, stored passwords, tokens and keys can only be read on this Spark; on another one they have to be entered again. A move backup brings the key for them, encrypted with your password: on the new Spark enter the same password in the field, then restore. Everyone has to sign in again afterwards. When restoring, the settings are checked like on the settings page, and either everything is swapped or nothing.","Umzugs-Passwort (mind. 12 Zeichen)": "Move password (at least 12 characters)","Umzugs-Sicherung anlegen": "Make move backup","Auf einen Blick": "At a glance","Update und Sicherung": "Update and backup","Alle Einstellungen des Spark mit ihrem Stand. Antippen öffnet die Seite.": "All settings of the Spark with their state. Tap to open the page.","Welches Modell antwortet und wie genau.": "Which model answers and how precisely.","Verbindung": "Connection","Schlüssel": "Key","Bei qwen38 übernimmt das Update ihn selbst.": "With qwen38 the update takes it over by itself.","Mehr": "More","Weniger": "Less","Er steht auf dem Spark in ~/.config/qwen38/api-key. Leer lassen, wenn der Server keinen Schlüssel verlangt.": "It is on the Spark in ~/.config/qwen38/api-key. Leave empty if the server needs no key.","Antworten": "Answers","Grundton aller Antworten; die festen Regeln kommen immer dazu.": "Basic tone of all answers; the fixed rules are always added.","Standard": "Default","empfohlen": "recommended","Keine Uhrzeit, kein Datum und kein Betrag, der in keinem Werkzeug-Ergebnis steht.": "No time, date or amount that is not in a tool result.","Gilt bei Fragen nach Terminen, Mails, Erinnerungen, Ergebnissen und Ähnlichem, auch für Spielstände. Antwortet das Modell ohne nachzusehen, wird es einmal neu gefragt.": "Applies to questions about appointments, mails, reminders, results and the like, also scores. If the model answers without looking, it is asked once more.","Kleiner = hält sich enger an Werkzeug-Ergebnisse; 0.3 empfohlen, Qwen-Standard 0.7.": "Lower = sticks closer to tool results; 0.3 recommended, Qwen default 0.7.","Länge einer Antwort": "Length of an answer","Höchstens so viele Tokens pro Antwort.": "At most this many tokens per answer.","Werkzeuge": "Tools","Gilt, solange das Modell ein Werkzeug wählt; danach die Temperatur oben. 0.1 empfohlen.": "Applies while the model picks a tool; afterwards the temperature above. 0.1 recommended.","· Verlaufslänge, Websuchen, Zeitlimit, Wortwahl, Wiederholungen, Werkzeugpflicht": "· history length, web searches, time limit, word choice, repetitions, tool duty","Verlaufslänge": "History length","Wie viel vom bisherigen Gespräch das Modell mitbekommt, 4000 bis 64000.": "How much of the conversation so far the model gets, 4000 to 64000.","Zeichen": "characters","24000 Zeichen sind etwa 8000 Tokens. Mehr braucht ein Modell mit großem Kontextfenster und mehr Speicher.": "24000 characters are about 8000 tokens. More needs a model with a large context window and more memory.","Zeitlimit für eine Antwort": "Time limit for an answer","60 bis 600. Kürzer lohnt sich, wenn das Modell auf einem anderen Rechner läuft.": "60 to 600. Shorter pays off when the model runs on another computer.","Sekunden": "seconds","Wortwahl (top_p)": "Word choice (top_p)","0 = Standard des Servers, sonst 0.05 bis 1; kleiner = vorsichtigere Wortwahl.": "0 = the server's default, else 0.05 to 1; lower = more careful word choice.","Wiederholungen vermeiden (presence_penalty)": "Avoid repetitions (presence_penalty)","0 = Standard des Servers, bis 2; hilft, wenn das Modell sich wiederholt (Qwen: etwa 1).": "0 = the server's default, up to 2; helps when the model repeats itself (Qwen: about 1).","Kommt eines dieser Wörter vor, muss das Modell zuerst das Werkzeug benutzen.": "If one of these words appears, the model has to use the tool first.","Eine Zeile pro Werkzeug: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Nur ganze Wörter, höchstens 20 pro Werkzeug. Die eingebauten Wörter bleiben immer.": "One line per tool: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Whole words only, at most 20 per tool. The built-in words always stay.","Wie der Spark spricht: Modell, Stimme und wie Text vorgelesen wird.": "How the Spark speaks: model, voice and how text is read out.","Sprachausgabe an": "Speech output on","Aus = der Dienst wird gestoppt; es gibt keine gesprochenen Antworten.": "Off = the service is stopped; there are no spoken answers.","CustomVoice: feste Sprecher. VoiceDesign: Stimme per Beschreibung. Base: eigene Stimmen (Stimmen).": "CustomVoice: fixed speakers. VoiceDesign: voice by description. Base: own voices (Voices).","Name des Sprechers, z. B. ryan.": "Name of the speaker, e.g. ryan.","Gilt, wenn eine Anfrage keine Sprache nennt.": "Applies when a request names no language.","Datum, Uhrzeit, Geld und Kommazahlen werden immer ausgeschrieben, außer bei „unverändert“.": "Dates, times, money and decimals are always spelled out, except with \"unchanged\".","Eine Regel pro Zeile, „Wort = so gesprochen“; ganze Wörter, Groß-/Kleinschreibung egal.": "One rule per line, \"word = spoken like this\"; whole words, case does not matter.","· Port, Temperatur, Wortwahl, Seed, Engine": "· port, temperature, word choice, seed, engine","Der Port des Dienstes auf dem Spark.": "The port of the service on the Spark.","Anteil am ganzen 128-GB-Pool.": "Share of the whole 128 GB pool.","Mehr braucht mehr Speicher.": "More needs more memory.","Kleiner erster Block = früher hörbar, größerer = läuft gleichmäßiger an.": "Smaller first block = heard earlier, larger = starts more evenly.","Stimme per Beschreibung.": "Voice by description.","bfloat16 passt für die meisten Grafikkarten.": "bfloat16 fits most graphics cards.","Eigene Stimmen für die Sprachausgabe: aufnehmen, anhören, sichern.": "Own voices for the speech output: record, listen, back up.","Stimme hinzufügen": "Add a voice","· aufnehmen oder Audiodatei hochladen": "· record or upload an audio file","So heißt die Stimme später in der Auswahl.": "The voice is listed under this name.","Lies den Text ruhig vor, so wie die Stimme später klingen soll.": "Read the text calmly, the way the voice should sound later.","… oder eine Audiodatei hochladen": "… or upload an audio file","Datei wählen …": "Choose file …","Genau der gesprochene Text; die Spracherkennung trägt ihn nach einer Aufnahme ein.": "Exactly the spoken text; speech recognition fills it in after a recording.","Eine ZIP-Datei mit Referenz-Audio und Transkript, etwa zum Sichern.": "A ZIP file with reference audio and transcript, e.g. as a backup.","Exportieren": "Export","ZIP importieren": "Import ZIP","Stimmen von einem anderen Spark übernehmen.": "Take over voices from another Spark.","Wie der Spark gesprochene Sätze in Text verwandelt.": "How the Spark turns spoken sentences into text.","Spracherkennung an": "Speech recognition on","Aus = der Dienst wird gestoppt; Sprechen mit dem Assistenten geht dann nicht.": "Off = the service is stopped; talking to the assistant does not work then.","Qwen3-ASR auf der Grafikkarte oder Parakeet auf dem Prozessor.": "Qwen3-ASR on the graphics card or Parakeet on the processor.","Namen und Fachbegriffe, die die Erkennung erwarten soll (z. B. DGX Spark, Qwen, Open WebUI).": "Names and technical terms recognition should expect (e.g. DGX Spark, Qwen, Open WebUI).","· Port, Engine": "· port, engine","Wie viele Aufnahmen auf einmal erkannt werden.": "How many recordings are recognized at once.","Obergrenze für den Text einer Aufnahme.": "Upper limit for the text of one recording.","Wer den Spark erreicht und wie du dich als Admin anmeldest.": "Who reaches the Spark and how you sign in as admin.","Wer den Spark erreicht": "Who reaches the Spark","wirkt mit Speichern": "applies on save","An: Startseite für alle im Netz, auch Gäste.": "On: start page for everyone in the network, guests too.","Aus: nur angemeldete Profile (Name und PIN) und Geräte mit Schlüssel, keine Gäste. Einstellungen bleiben immer geschützt.": "Off: only signed-in profiles (name and PIN) and devices with a key, no guests. Settings always stay protected.","Heimnetz-Adressen erlauben": "Allow home network addresses","Kalender, Kontakte und Mail der Profile dürfen auch auf Servern im Heimnetz liegen.": "Calendars, contacts and mail of the profiles may also be on servers in the home network.","Nur diesen Adressen wird die weitergereichte Absender-Adresse geglaubt.": "Only these addresses are trusted with the forwarded sender address.","Gemeint ist X-Forwarded-For. Leer = nur ein Proxy auf dem Spark selbst. Eintragen, wenn das Panel hinter einem Proxy im Heimnetz hängt: sonst teilen sich alle, die über den Proxy kommen, eine Adresse für die Sperre nach falschen Passwörtern.": "This is X-Forwarded-For. Empty = only a proxy on the Spark itself. Fill in when the panel sits behind a proxy in the home network: otherwise everyone coming through the proxy shares one address for the lock after wrong passwords.","Gesetzt = Apps senden „Authorization: Bearer <Schlüssel>“; leer = ohne Schlüssel.": "Set = apps send \"Authorization: Bearer <key>\"; empty = no key.","wirkt sofort, ohne Speichern": "applies at once, without saving","Ändern …": "Change …","Code aus einer Authenticator-App bei jeder Admin-Anmeldung.": "Code from an authenticator app at every admin sign-in.","Solange er an ist, geht die Anmeldung per HTTP-Basic (Skripte) nicht mehr, und Passwort ändern, Sicherung wiederherstellen, Geräteschlüssel anlegen oder umhängen und PINs ändern fragen jedes Mal nach einem Code. Notausgang ohne Handy und Codes: auf dem Spark sudo rm /var/lib/speech-spark/state/mfa-admin.json": "While it is on, sign-in by HTTP Basic (scripts) no longer works, and changing the password, restoring a backup, creating or moving device keys and changing PINs ask for a code every time. Way out without phone and codes: on the Spark sudo rm /var/lib/speech-spark/state/mfa-admin.json","Beendet die Admin-Anmeldung in allen Browsern, auch hier (z. B. nach einem verlorenen Gerät).": "Ends the admin sign-in in every browser, here too (e.g. after a lost device).","Wie der Spark mit Speicher, hängenden Diensten, Logs und Ports umgeht.": "How the Spark handles memory, hanging services, logs and ports.","Warnen unter": "Warn below","GiB frei": "GiB free","Hängende Dienste neu starten": "Restart hanging services","Startet ASR, TTS oder eine Engine neu, wenn sie hängt; höchstens dreimal pro Stunde.": "Restarts ASR, TTS or an engine when it hangs; at most three times an hour.","Hängen heißt: 5 Minuten keine Antwort, 5 Minuten arbeiten, ohne eine Anfrage fertigzustellen, oder 45 Minuten laden. Jeder Neustart steht im Änderungsprotokoll.": "Hanging means: no answer for 5 minutes, working for 5 minutes without finishing a request, or loading for 45 minutes. Every restart is in the change log.","Höchstens so viel Platz": "At most this much space","Aufbewahren": "Keep","Wirkt nach dem nächsten Update oder sudo ./install.sh.": "Applies after the next update or sudo ./install.sh.","Tage": "days","Neue geprüfte Versionen holen und sichern, was der Spark weiß.": "Get new tested versions and back up what the Spark knows.","Ein Update holt den neuesten Stand von GitHub und installiert ihn. Einstellungen, Modelle und Stimmen bleiben. Vor dem Umschalten prüft ein Selbsttest die neue Version; schlägt er oder ein Schritt davor fehl, läuft die bisherige Version unverändert weiter. Geht nach dem Umschalten etwas schief, wird die bisherige Version wieder eingespielt. Während des Updates starten die Dienste kurz neu.": "An update gets the newest state from GitHub and installs it. Settings, models and voices stay. Before switching over, a self-test checks the new version; if it or a step before fails, the current version keeps running unchanged. If something goes wrong after switching, the previous version is put back. During the update the services restart briefly.","wirkt sofort": "applies at once","Stand": "State","jeden Tag automatisch": "automatically every day","Was gesichert wird": "What is backed up","Profile, geklonte Stimmen, Einstellungen und was der Spark für alle hält.": "Profiles, cloned voices, settings and what the Spark keeps for everyone.","Legt sofort eine Sicherung auf dem Spark an.": "Makes a backup on the Spark right now.","Sichern": "Back up","Aus Datei wiederherstellen": "Restore from file","Eine heruntergeladene Sicherung (.tar.gz) einspielen.": "Restore a downloaded backup (.tar.gz).","Umzugs-Sicherung": "Move backup","Für einen anderen Spark: bringt den Schlüssel für Passwörter und Tokens mit.": "For another Spark: brings the key for passwords and tokens along.","· was beim letzten Update passiert ist": "· what happened during the last update","Welche Stimme der Assistent nutzt, steht unter Sprachausgabe → Standardstimme; jedes Profil kann sich unter Ich → Gespräch eine andere wählen. Wer spricht, erkennt dagegen die Sprechererkennung.": "Which voice the assistant uses is set under Speech output → default voice; every profile can choose another one under Me → Conversation. Who is speaking is recognized by speaker recognition instead.","Angemeldete Browser": "Signed-in browsers","Meldet dein Profil in allen anderen Browsern ab; dieser bleibt angemeldet. Geräte mit Schlüssel (Lautsprecher, Uhr) sperrst du oben einzeln. Einzelne Browser meldest du in der Liste darüber ab. Eine Anmeldung endet außerdem nach": "Logs your profile out in all other browsers; this one stays signed in. Devices with a key (speakers, watch) are blocked one by one above. Single browsers are signed out in the list above it. A sign-in also ends after","Tagen ohne Nutzung. Mit zweitem Anmeldeschritt müssen auch vertraute Browser danach wieder einen Code eingeben.": "days without use. With the second sign-in step, trusted browsers have to enter a code again afterwards.","Anmeldung im Browser": "Sign-in in the browser","Ein Profil bleibt so viele Tage ohne Nutzung angemeldet (7 bis 90).": "A profile stays signed in for this many days without use (7 to 90).","rot = offen, gelb = empfohlen, grün = gut": "red = open, yellow = recommended, green = fine"};
function translatePage(){document.documentElement.lang=L;$('langbtn').textContent=L==='en'?'Deutsch':'English';if(L!=='en')return;
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('pre,code,script,style,option:not([value])')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  for(let n;(n=w.nextNode());){const k=n.nodeValue.trim();if(EN[k]!==undefined)n.nodeValue=n.nodeValue.replace(k,EN[k])}
  document.querySelectorAll('[placeholder]').forEach(e=>{if(EN[e.placeholder])e.placeholder=EN[e.placeholder]});
  const tx=$('ttstext');if(EN[tx.value])tx.value=EN[tx.value];}
$('langbtn').onclick=()=>{try{localStorage.setItem('lang',L==='en'?'de':'en')}catch{}location.reload()};
translatePage();
